import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    trades = inputs["trades"].copy()

    # Ensure correct dtypes
    trades["trade_id"] = trades["trade_id"].astype("int64")
    trades["account_id"] = trades["account_id"].astype("int64")
    trades["symbol"] = trades["symbol"].astype("str")
    trades["side"] = trades["side"].astype("str")
    trades["qty"] = trades["qty"].astype("int64")
    trades["price"] = trades["price"].astype("float64")
    trades["trade_ts"] = pd.to_datetime(trades["trade_ts"])

    # Sort by account_id, symbol, then trade_ts, then trade_id (FIFO order)
    trades = trades.sort_values(
        by=["account_id", "symbol", "trade_ts", "trade_id"],
        ignore_index=True
    )

    sell_results_list = []
    open_lots_list = []

    # Process each (account_id, symbol) group separately
    for (account_id, symbol), group_trades in trades.groupby(
        ["account_id", "symbol"], sort=False
    ):
        # Track open lots in FIFO order: each is [lot_trade_id, remaining_qty, price]
        open_lots = {}  # lot_trade_id -> {"remaining_qty": int, "price": float}

        for _, trade in group_trades.iterrows():
            trade_id = trade["trade_id"]
            side = trade["side"]
            qty = trade["qty"]
            price = trade["price"]

            if side == "BUY":
                # Open a new lot
                open_lots[trade_id] = {
                    "remaining_qty": qty,
                    "price": price,
                    "trade_ts": trade["trade_ts"],
                }
            elif side == "SELL":
                # Match against open lots in FIFO order
                matched_qty = 0
                realized_pnl = 0.0
                still_to_sell = qty

                # Iterate through lots in the order they were created (by trade_id within this group)
                lot_ids_in_order = [
                    lot_id
                    for lot_id in group_trades[group_trades["side"] == "BUY"]["trade_id"]
                    if lot_id in open_lots and open_lots[lot_id]["remaining_qty"] > 0
                ]

                for lot_trade_id in lot_ids_in_order:
                    if still_to_sell <= 0:
                        break

                    lot = open_lots[lot_trade_id]
                    take = min(lot["remaining_qty"], still_to_sell)

                    realized_pnl += take * (price - lot["price"])
                    lot["remaining_qty"] -= take
                    matched_qty += take
                    still_to_sell -= take

                short_qty = qty - matched_qty

                sell_results_list.append({
                    "trade_id": trade_id,
                    "matched_qty": matched_qty,
                    "short_qty": short_qty,
                    "realized_pnl": realized_pnl,
                })

        # Collect remaining open lots
        for lot_trade_id, lot_info in open_lots.items():
            if lot_info["remaining_qty"] > 0:
                open_lots_list.append({
                    "lot_trade_id": lot_trade_id,
                    "account_id": account_id,
                    "symbol": symbol,
                    "remaining_qty": lot_info["remaining_qty"],
                    "price": lot_info["price"],
                })

    # Create output DataFrames
    if sell_results_list:
        sell_results = pd.DataFrame(sell_results_list)
        sell_results = sell_results.astype({
            "trade_id": "int64",
            "matched_qty": "int64",
            "short_qty": "int64",
            "realized_pnl": "float64",
        })
    else:
        sell_results = pd.DataFrame(
            columns=["trade_id", "matched_qty", "short_qty", "realized_pnl"]
        ).astype({
            "trade_id": "int64",
            "matched_qty": "int64",
            "short_qty": "int64",
            "realized_pnl": "float64",
        })

    if open_lots_list:
        open_lots = pd.DataFrame(open_lots_list)
        open_lots = open_lots.astype({
            "lot_trade_id": "int64",
            "account_id": "int64",
            "symbol": "str",
            "remaining_qty": "int64",
            "price": "float64",
        })
    else:
        open_lots = pd.DataFrame(
            columns=["lot_trade_id", "account_id", "symbol", "remaining_qty", "price"]
        ).astype({
            "lot_trade_id": "int64",
            "account_id": "int64",
            "symbol": "str",
            "remaining_qty": "int64",
            "price": "float64",
        })

    return {
        "sell_results": sell_results,
        "open_lots": open_lots,
    }
